class Main {void main(String[] args)throws java.io.IOException {char[] chars=new String(System.in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).toCharArray();var out=new StringBuilder();int count=0;for(char c:chars){if(c=='.')break;char next=c;if(c>='a'&&c<='z'){next=(char)(c-32);count++;}else if(c>='A'&&c<='Z'){next=(char)(c+32);count++;}out.append(next);}System.out.print(out+"\r\n"+count+"\r\n");}}
